    if (bitsRead + 3 > numBits) {
      return false;
    }
    if (bitsRead >>> 3 < tailBase) {
      window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
    } else {
      window = tailWord >>> (bitsRead - tailBase * 8);
    }
    v = window & 0x7;
    bitsRead += 3;
    if (v > 4) {
      return false; // not a wire-legal tag (SPEC §4.8)
    }
    e0.type = v;
    switch (e0.type) {
      case 1:
        break; // a payload-free arm: the tag is the whole wire (SPEC §4.8)
      case 2:
        e0.pulse.strength = 0;
        if (bitsRead + 16 > numBits) {
          return false;
        }
        if (bitsRead >>> 3 < tailBase) {
          window =
              view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
        } else {
          window = tailWord >>> (bitsRead - tailBase * 8);
        }
        v = window & 0xffff;
        bitsRead += 16;
        e0.pulse.strength = v;
      case 3:
        e0.level.level = 0;
        if (bitsRead + 3 > numBits) {
          return false;
        }
        if (bitsRead >>> 3 < tailBase) {
          window =
              view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
        } else {
          window = tailWord >>> (bitsRead - tailBase * 8);
        }
        v = window & 0x7;
        bitsRead += 3;
        e0.level.level = v;
      case 4:
        break; // a payload-free arm: the tag is the whole wire (SPEC §4.8)
    }
  }
  if (bitsRead + 3 > numBits) {
    return false;
  }
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0x7;
  bitsRead += 3;
  value.tail = v;
  return true;
}

// measureVoidSignalPacket is the exact wire bits writeVoidSignalPacket would produce for value —
// trusted like the writer; static runs fold to literals at generation time.
int measureVoidSignalPacket(VoidSignalPacket value) {
  var bits = 0;
  bits += 3;
  bits += 3;
  switch (value.signal.type) {
    case 1:
      break; // a payload-free arm: the tag is the whole wire (SPEC §4.8)
    case 2:
      bits += 16;
    case 3:
      bits += 3;
    case 4:
      break; // a payload-free arm: the tag is the whole wire (SPEC §4.8)
  }
  bits += 3;
  switch (value.echo.type) {
    case 1:
      break; // a payload-free arm: the tag is the whole wire (SPEC §4.8)
    case 2:
      bits += 16;
    case 3:
      bits += 3;
    case 4:
      break; // a payload-free arm: the tag is the whole wire (SPEC §4.8)
  }
  bits += 2;
  for (var i0 = 0; i0 < value.historyCount; i0++) {
    final e0 = value.history[i0];
    bits += 3;
    switch (e0.type) {
      case 1:
        break; // a payload-free arm: the tag is the whole wire (SPEC §4.8)
      case 2:
        bits += 16;
      case 3:
        bits += 3;
      case 4:
        break; // a payload-free arm: the tag is the whole wire (SPEC §4.8)
    }
  }
  bits += 3;
  return bits;
}
